head.b:skin:
:root{--c:__COLOR__;--c2:__COLOR2__;--ink:#0f172a;--mut:#64748b;--bg:#eef3f9;--card:#fff;--line:#e3eaf3;--navy:#071a33;--soft:color-mix(in srgb,var(--c) 12%,#fff)}
@media (prefers-color-scheme:dark){:root{--ink:#e5edf7;--mut:#94a3b8;--bg:#0a1324;--card:#111c31;--line:#1e2b43;--soft:color-mix(in srgb,var(--c) 18%,#111c31)}}
*{box-sizing:border-box}html{scroll-behavior:smooth}
body{margin:0;font-family:Tajawal,system-ui,sans-serif;background:var(--bg);color:var(--ink);line-height:1.8;padding-bottom:calc(80px + env(safe-area-inset-bottom))}
a{color:var(--c);text-decoration:none}svg{width:1em;height:1em;flex:none}
.shell{display:flex;min-height:100vh}
.side{width:240px;flex:none;position:sticky;top:0;height:100vh;background:var(--card);border-inline-start:1px solid var(--line);display:flex;flex-direction:column;padding:14px 12px;order:0}
.logo{display:flex;align-items:center;gap:10px;padding:2px 6px 16px}
.logo .m{width:44px;height:44px;border-radius:14px;background:linear-gradient(135deg,var(--c),var(--c2));color:#fff;display:grid;place-items:center;font-size:22px;box-shadow:0 6px 16px color-mix(in srgb,var(--c) 40%,transparent)}
.logo b{display:block;font-weight:900;font-size:19px;letter-spacing:.3px;color:var(--ink)}.logo small{display:block;font-size:11px;font-weight:700;color:var(--c)}
.snav{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:2px;overflow:auto}
.snav a{display:flex;align-items:center;gap:12px;padding:9px 12px;border-radius:12px;color:var(--ink);font-size:14px;font-weight:500}
.snav a svg{font-size:18px;color:var(--mut)}.snav a:hover,.snav a.on{background:var(--soft);color:var(--c);font-weight:700}.snav a.on svg,.snav a:hover svg{color:var(--c)}
.snav .sep{height:1px;background:var(--line);margin:8px 6px}
.side .staff{margin-top:auto;border-top:1px solid var(--line);padding-top:10px}
.main{flex:1;min-width:0}
.top{position:sticky;top:0;z-index:20;background:color-mix(in srgb,var(--bg) 85%,transparent);backdrop-filter:blur(10px)}
.top .in{max-width:760px;margin:0 auto;padding:10px 16px;display:flex;align-items:center;gap:10px}
.cb{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;flex:none;font-size:18px;border:0;cursor:pointer}
.cb.p{background:linear-gradient(135deg,var(--c),var(--c2));color:#fff;box-shadow:0 4px 12px color-mix(in srgb,var(--c) 40%,transparent)}
.cb.g{background:var(--card);color:var(--mut);border:1px solid var(--line)}
.dhikr{flex:1;min-width:0;overflow:hidden;background:var(--card);border:1px solid var(--line);border-radius:999px;height:34px;display:flex;align-items:center}
.dhikr span{white-space:nowrap;display:inline-block;padding-inline-start:100%;animation:tk 28s linear infinite;color:#047857;font-weight:800;font-size:13px}
@keyframes tk{to{transform:translateX(100%)}}
.wrap{max-width:760px;margin:0 auto;padding:0 16px}
.ban{position:relative;overflow:hidden;border-radius:28px;height:19rem;background:var(--navy);color:#fff;margin-top:6px;box-shadow:0 18px 40px rgba(7,26,51,.25)}
.ban img{position:absolute;inset:0 auto 0 0;width:78%;height:100%;object-fit:cover;opacity:.9;-webkit-mask-image:linear-gradient(to right,#000 45%,transparent);mask-image:linear-gradient(to right,#000 45%,transparent);transition:opacity .6s}
.ban:before{content:'';position:absolute;inset:0;background:radial-gradient(circle at 85% 20%,color-mix(in srgb,var(--c) 40%,transparent),transparent 45%),linear-gradient(to left,var(--navy) 30%,rgba(7,26,51,.55) 65%,rgba(7,26,51,.05));z-index:1}
.ban:after{content:'';position:absolute;inset:0;opacity:.12;background-image:linear-gradient(rgba(125,211,252,.6) 1px,transparent 1px),linear-gradient(90deg,rgba(125,211,252,.6) 1px,transparent 1px);background-size:26px 26px;z-index:1}
.ban .bx{position:relative;z-index:2;height:100%;display:flex;flex-direction:column;justify-content:space-between;padding:20px}
.badge{display:inline-flex;align-items:center;gap:6px;font-size:11px;font-weight:900;background:rgba(255,255,255,.1);border:1px solid rgba(125,211,252,.3);border-radius:999px;padding:2px 10px}
.badge i{width:7px;height:7px;border-radius:50%;background:#34d399;animation:pl 1.6s infinite}@keyframes pl{50%{opacity:.3}}
.ban h1{margin:6px 0 0;font-size:32px;font-weight:900;letter-spacing:.5px;display:flex;align-items:center;gap:8px}
.ban h1 svg{color:#bae6fd;font-size:26px}
.ban .sub{margin:0;font-weight:900;font-size:14px;color:#bae6fd}
.slide .t{display:flex;align-items:center;gap:10px;font-weight:900;font-size:21px}
.slide .ic{width:44px;height:44px;border-radius:16px;display:grid;place-items:center;font-size:22px;color:#fff;box-shadow:0 6px 14px rgba(0,0,0,.25);outline:2px solid rgba(255,255,255,.3)}
.slide .ls{margin-top:10px;display:flex;flex-wrap:wrap;gap:6px;max-width:92%}
.slide .ls span{display:inline-flex;align-items:center;gap:4px;font-size:12px;font-weight:700;background:rgba(255,255,255,.1);backdrop-filter:blur(8px);border:1px solid rgba(255,255,255,.15);border-radius:999px;padding:3px 10px}
.slide .ls svg{color:#6ee7b7}
.slide{animation:fi .5s}@keyframes fi{from{opacity:0;transform:translateY(6px)}}
.promo{display:flex;gap:8px;align-items:center}
.promo a{display:flex;align-items:center;justify-content:center;gap:6px;border-radius:12px;padding:8px 12px;font-size:13px;font-weight:800}
.promo .dl{flex:1;background:#fff;color:var(--ink)}.promo .sh{background:rgba(255,255,255,.08);color:#e2e8f0;border:1px solid rgba(255,255,255,.2)}
.cnt{position:absolute;top:16px;left:16px;z-index:3;display:flex;align-items:center;gap:6px;font-size:10px;font-weight:800;color:#cbd5e1}.cnt i{width:56px;height:4px;border-radius:9px;background:rgba(255,255,255,.2);overflow:hidden}.cnt u{display:block;height:100%;width:6%;background:#7dd3fc;transition:width .4s}
.slide .ob{display:inline-flex;align-items:center;gap:6px;margin-top:12px;background:linear-gradient(90deg,var(--c2),var(--c));color:#fff;border-radius:999px;padding:8px 16px;font-weight:900;font-size:13px;box-shadow:0 6px 14px rgba(0,0,0,.25)}
.search{display:flex;align-items:center;gap:8px;background:var(--card);border:1px solid var(--line);border-radius:999px;padding:6px 8px 6px 14px;margin-top:16px;color:var(--c)}
.search input{flex:1;border:0;background:transparent;font:inherit;font-size:14px;color:var(--ink);outline:0;min-width:0}
.search .flt{width:32px;height:32px;border-radius:50%;background:var(--soft);display:grid;place-items:center;color:var(--c)}
.offer{position:relative;overflow:hidden;border-radius:26px;height:11rem;background:var(--navy);color:#fff;margin-top:16px}
.offer img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.55}
.offer:before{content:'';position:absolute;inset:0;background:linear-gradient(to left,rgba(7,26,51,.95) 25%,rgba(7,26,51,.3));z-index:1}
.offer .ox{position:relative;z-index:2;padding:16px 18px}.offer .tag{background:#facc15;color:#422006;font-weight:900;font-size:11px;border-radius:999px;padding:2px 10px}
.offer h3{margin:8px 0 2px;font-size:clamp(19px,4.6vw,28px);font-weight:900}.offer p{margin:0;font-size:12px;color:#cbd5e1}
.offer .go{display:inline-flex;align-items:center;gap:6px;margin-top:10px;background:linear-gradient(90deg,var(--c2),var(--c));color:#fff;border-radius:999px;padding:7px 16px;font-weight:900;font-size:13px}
.offer .dots{position:absolute;bottom:10px;left:50%;transform:translateX(-50%);z-index:2;display:flex;gap:5px}.offer .dots i{width:7px;height:7px;border-radius:9px;background:rgba(255,255,255,.4)}.offer .dots i.on{width:20px;background:#fff}
.appc{position:relative;overflow:hidden;border-radius:24px;background:linear-gradient(90deg,#0b2545,#0f3a5f,color-mix(in srgb,var(--c) 60%,#0f3a5f));color:#fff;margin-top:16px;padding:14px}
.appc .h{display:flex;align-items:center;gap:10px}.appc .gi{width:42px;height:42px;border-radius:14px;background:rgba(255,255,255,.12);display:grid;place-items:center;font-size:20px}
.appc b{display:block;font-weight:900}.appc small{font-size:12px;color:#cbd5e1}
.appc .promo{margin:12px 0 0;padding:0;background:none}
.tiles{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:16px}
@media (max-width:560px){.tiles{grid-template-columns:repeat(3,1fr)}}
.tile{position:relative;overflow:hidden;background:var(--card);border:1px solid var(--line);border-radius:18px;padding:12px 6px 10px;display:flex;flex-direction:column;align-items:center;gap:8px;color:var(--ink);box-shadow:0 2px 6px rgba(15,23,42,.04);transition:transform .15s}
.tile:before{content:'';position:absolute;top:-22px;right:-22px;width:56px;height:56px;border-radius:50%;background:color-mix(in srgb,var(--c) 10%,transparent)}
.tile:hover{transform:translateY(-2px)}
.tile .ic{width:48px;height:48px;border-radius:16px;display:grid;place-items:center;color:#fff;font-size:22px;box-shadow:0 6px 14px rgba(15,23,42,.15);position:relative}
.tile b{font-size:13px;font-weight:900;text-align:center;line-height:1.4}
.more{display:flex;justify-content:center;align-items:center;gap:4px;font-size:12px;font-weight:700;margin:10px 0 0}
.acts{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:16px}
.act{position:relative;overflow:hidden;border-radius:18px;color:#fff;padding:14px 8px;display:flex;flex-direction:column;align-items:center;gap:6px;text-align:center}
.act .ic{width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,.2);display:grid;place-items:center;font-size:18px}
.act b{font-weight:900;font-size:14px}.act small{font-size:11px;opacity:.85}
.act.call{background:linear-gradient(135deg,#f43f5e,#db2777)}.act.order{background:linear-gradient(135deg,var(--c),var(--c2))}.act.wa{background:linear-gradient(135deg,#10b981,#16a34a)}
.ai{position:relative;overflow:hidden;border-radius:26px;background:linear-gradient(135deg,color-mix(in srgb,var(--c) 14%,#fff),#f8fbff);border:1px solid var(--line);padding:16px;margin-top:16px;display:flex;gap:12px}
@media (prefers-color-scheme:dark){.ai{background:var(--card)}}
.ai .bot{width:64px;height:64px;border-radius:20px;background:linear-gradient(135deg,var(--c),var(--c2));color:#fff;display:grid;place-items:center;font-size:30px;flex:none;position:relative}
.ai .bot small{position:absolute;bottom:8px;left:10px;font-weight:900;font-size:13px}
.ai .msg{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:10px 12px;font-size:13px}
.ai .msg b{color:var(--c)}
.ai .go{display:flex;align-items:center;justify-content:center;gap:6px;margin-top:8px;background:linear-gradient(90deg,var(--c2),var(--c));color:#fff;border-radius:999px;padding:9px;font-weight:900;font-size:13px}
.chips{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}
.chips a,.chips span{background:var(--card);border:1px solid var(--line);border-radius:999px;padding:4px 12px;font-size:12px;color:var(--ink)}
section.blk{margin-top:26px}
.blk h2{font-size:20px;font-weight:900;margin:0 0 4px}.blk .sb{color:var(--mut);margin:0 0 12px;font-size:14px}
.card{background:var(--card);border:1px solid var(--line);border-radius:22px;padding:16px;margin-bottom:12px;box-shadow:0 2px 6px rgba(15,23,42,.04)}
.feat h3{margin:0 0 6px;font-size:18px;display:flex;align-items:center;gap:8px}.feat h4{margin:12px 0 4px;color:var(--c);font-size:15px}
.two{display:grid;grid-template-columns:1fr 1fr;gap:14px}@media (max-width:600px){.two{grid-template-columns:1fr}}
ul.tk{list-style:none;padding:0;margin:0}ul.tk li{display:flex;gap:6px;align-items:flex-start;margin:3px 0;font-size:14px}ul.tk li svg{color:#10b981;margin-top:5px}
ul.wr li svg{color:#f43f5e}
details{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:9px 13px;margin:7px 0}details summary{cursor:pointer;font-weight:800}
.svcs{display:grid;grid-template-columns:1fr 1fr;gap:8px}@media (max-width:600px){.svcs{grid-template-columns:1fr}}.svcs details{margin:0}
.btn{display:inline-flex;align-items:center;gap:6px;background:linear-gradient(90deg,var(--c2),var(--c));color:#fff;padding:9px 18px;border-radius:999px;font-weight:900;font-size:14px;margin-top:10px}
.steps{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;counter-reset:s}@media (max-width:560px){.steps{grid-template-columns:1fr}}
.steps div{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:14px}
.steps div:before{counter-increment:s;content:counter(s);display:inline-grid;place-items:center;width:28px;height:28px;border-radius:50%;background:linear-gradient(135deg,var(--c),var(--c2));color:#fff;font-weight:900;margin-bottom:4px}
.steps p{margin:2px 0 0;color:var(--mut);font-size:13px}
.cov h4{margin:0 0 6px}
.posts{display:grid;grid-template-columns:1fr 1fr;gap:10px}@media (max-width:600px){.posts{grid-template-columns:1fr}}
.pc{background:var(--card);border:1px solid var(--line);border-radius:20px;padding:14px;display:flex;flex-direction:column}
.pc .k{font-size:11px;font-weight:800;color:var(--c);background:var(--soft);border-radius:999px;padding:1px 10px;width:fit-content}
.pc h3{font-size:16px;margin:6px 0 4px;line-height:1.5}.pc p{color:var(--mut);font-size:13px;margin:0 0 6px;flex:1}
.net{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:6px}@media (max-width:600px){.net{grid-template-columns:1fr}}
.net a{display:flex;gap:8px;align-items:center;font-size:13px;color:var(--ink);background:var(--card);border:1px solid var(--line);border-radius:12px;padding:8px 12px}.net i{width:9px;height:9px;border-radius:50%;flex:none}
.post h1{margin:0 0 4px;font-size:clamp(21px,3.4vw,28px);line-height:1.5}.meta{color:var(--mut);font-size:13px;margin-bottom:12px}
.post-body img{max-width:100%;height:auto;border-radius:14px}.post-body h2,.post-body h3{line-height:1.5}
.box{background:linear-gradient(135deg,var(--c),var(--c2));color:#fff;border-radius:20px;padding:16px;text-align:center;margin:16px 0}
.box a{display:inline-block;margin-top:8px;background:#fff;color:var(--c);padding:8px 18px;border-radius:999px;font-weight:900}
.tags .widget{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:12px 14px;margin:16px 0}.tags h2{font-size:15px;margin:0 0 6px}.tags ul{list-style:none;padding:0;margin:0;display:flex;flex-wrap:wrap;gap:6px}.tags li a{display:inline-block;background:var(--soft);padding:2px 10px;border-radius:999px;font-size:12px}
.foot{text-align:center;color:var(--mut);font-size:11px;padding:20px 16px 8px}
.fab{position:fixed;left:18px;bottom:96px;z-index:25;display:flex;flex-direction:column;gap:10px}
.fab a{width:52px;height:52px;border-radius:50%;display:grid;place-items:center;color:#fff;font-size:21px;box-shadow:0 8px 18px rgba(15,23,42,.25)}
.fab .f1{background:linear-gradient(135deg,var(--c),var(--c2))}.fab .f2{background:#16a34a}.fab .f3{background:#7c3aed}.fab .f4{background:#e11d48}
.bar{display:none;position:fixed;inset:auto 0 0 0;z-index:30;background:var(--card);border-top:1px solid var(--line);grid-template-columns:repeat(5,1fr);padding:6px 4px calc(6px + env(safe-area-inset-bottom))}
.bar a{display:flex;flex-direction:column;align-items:center;gap:2px;font-size:11px;color:var(--mut)}.bar a svg{font-size:21px}
.bar a.o span{color:var(--c);font-weight:900}.bar a.o i{width:48px;height:48px;border-radius:50%;background:linear-gradient(135deg,var(--c),var(--c2));color:#fff;display:grid;place-items:center;margin-top:-22px;font-size:22px;box-shadow:0 6px 16px color-mix(in srgb,var(--c) 45%,transparent)}
@media (max-width:900px){.side{display:none}.bar{display:grid}.fab{bottom:92px;left:12px}.fab a{width:46px;height:46px}}
@media (min-width:901px){body{padding-bottom:0}}
#appx{position:fixed;inset:0;z-index:100;background:var(--bg);display:none;flex-direction:column}#appx.on{display:flex}
#appx .hd{display:flex;align-items:center;gap:10px;padding:8px 12px;background:linear-gradient(90deg,var(--c2),var(--c));color:#fff;font-weight:900}
#appx .hd button{margin-inline-start:auto;background:rgba(255,255,255,.2);color:#fff;border:0;border-radius:999px;padding:6px 14px;font:inherit;cursor:pointer}
#appx iframe{flex:1;border:0;width:100%}
body.lock{overflow:hidden}
